                throw new InvalidClaimException("Claim " + number + ": no claim can be added inside a closed period");
            }
            if (!person.allowsClaimOn(date)) {
                throw new InvalidClaimException("Claim " + number + ": no claim can be dated after the person's retirement date");
            }
            persons.add(person);
            dates.add(date);
        }
        for (int i = 0; i < request.lines().size(); i++) {
            ValidClaim valid = request.lines().get(i).claim();
            Person person = persons.get(i);
            LocalDate date = dates.get(i);
            Claim claim = claims.add(sheetId, person.getId(), valid.amount(), date, valid.note(),
                    date.plusDays(settings.termsFor(sheetId, person.getTerms(), person.gradeOn(date), date)));
            log.record(claim, person, request.user());
            audit.recordOnCommit(ClaimAudit.line("CLAIM_ADDED", request.user(), person, claim, claim.getNumber()));
            LateEntry.mark(claim, person, request.user(), claims, periods, audit);
        }
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new PasteClaimsResponse(request.lines().size()));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ValidClaim request, @Val Claim claim, Sheets sheets, Periods periods, People people, Claims claims)
            throws InvalidClaimException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            // Only a draft can be edited; to change an open claim, void it and add a new one.
            throw new InvalidClaimException("Only a DRAFT claim can be edited");
        }
        String lockedBy = claims.lockedBy(claim);
        if (lockedBy != null && !lockedBy.equals(request.user())) {
            throw new InvalidClaimException("The claim is being edited by " + lockedBy);
        }
        LocalDate date = request.date() != null ? request.date() : sheets.today(claim.getSheetId());
        if (periods.isClosed(claim.getSheetId(), claim.getDate()) || periods.isClosed(claim.getSheetId(), date)) {
            throw new InvalidClaimException("No claim dated inside a closed period can be edited");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (person != null && !person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        ValidateClaim.checkCorrects(request, claim.getSheetId(), claim.getPersonId(), claims);
        claim.setAmount(request.amount());
        claim.setCorrects(request.corrects());
        claim.setCorrectedDate(claims.correctedDate(claim.getSheetId(), claim.getPersonId(), request.corrects()));
        claim.setDate(date);
        claim.setNote(request.note());
    }
}

